-- Capture the then-current chain and remove only this ticket's closed objects.
alter function bitd.validate_character_patch(jsonb) rename to validate_character_pre_companion_patch;
create function bitd.validate_character_companion_patch(p_patch jsonb) returns void
language plpgsql set search_path = '' as $$
declare e record; n record; item jsonb; allowed text[];
begin
 for e in select * from jsonb_each(p_patch) where key in ('sparkmind','resonanceEntity','autopod','intellectual','paranormalist','swinger') loop
  if jsonb_typeof(e.value)<>'object' then raise exception 'Expected % record',e.key; end if;
  for n in select * from jsonb_each(e.value) loop
   if (e.key in ('sparkmind','resonanceEntity','autopod') and n.key in ('name','edges','flaws','origin','notes'))
    or (e.key='sparkmind' and n.key='housing') or (e.key='resonanceEntity' and n.key in ('type','kind','abilities'))
    or (e.key='autopod' and n.key in ('type','style')) or (e.key='intellectual' and n.key in ('fieldsOfStudy','gadgetDecisions','operations'))
    or (e.key='paranormalist' and n.key in ('experiments','operations')) or (e.key='swinger' and n.key in ('sideHustle','twinNotes','operations')) then
    if jsonb_typeof(n.value)<>'string' or length(n.value #>> '{}')>12000 then raise exception 'Invalid companion text'; end if;
    if e.key='sparkmind' and n.key='housing' and not (n.value #>> '{}')=any(array['','Small','Large']) then raise exception 'Choose Small or Large housing'; end if;
    if e.key='resonanceEntity' and n.key='type' and n.value<>'"Paranormal Assistant"'::jsonb then raise exception 'Entity is an expert Paranormal Assistant'; end if;
    if e.key='autopod' and n.key='type' and not (n.value #>> '{}')=any(array['','Racing','Impressing','Surprising']) then raise exception 'Choose an autopod type'; end if;
   elsif (e.key in ('sparkmind','resonanceEntity','autopod') and n.key in ('weak','impaired','broken')) or (e.key='resonanceEntity' and n.key='armor')
    or (e.key='paranormalist' and n.key='projectionActive') or (e.key='swinger' and n.key in ('hustleActivityGranted','partyAssistAvailable','twinSummoned')) then
    if jsonb_typeof(n.value)<>'boolean' then raise exception 'Invalid companion condition or use'; end if;
   elsif e.key='paranormalist' and n.key in ('precognitionUsed','projectionRank') then
    if not bitd.character_record_integer(n.value,2) then raise exception 'Ability has at most two selections or uses'; end if;
   elsif (e.key='sparkmind' and n.key in ('types','advancedChoices')) or (e.key='swinger' and n.key='twinFeatures') then
    if jsonb_typeof(n.value)<>'array' or jsonb_array_length(n.value)>(case when n.key='advancedChoices' then 2 else 3 end) then raise exception 'Invalid companion choices'; end if;
    allowed := case n.key when 'types' then array['Research','Analysis','Ingress'] when 'advancedChoices' then array['additional-type','add-edge','remove-flaw'] else array['scene','solid','obedient'] end;
    for item in select * from jsonb_array_elements(n.value) loop
     if jsonb_typeof(item)<>'string' or not (item #>> '{}')=any(allowed) then raise exception 'Unknown companion choice'; end if;
    end loop;
    if n.key<>'advancedChoices' and (select count(*)<>count(distinct value) from jsonb_array_elements(n.value)) then raise exception 'Duplicate companion choice'; end if;
   else raise exception 'Unknown % field: %',e.key,n.key; end if;
  end loop;
 end loop;
end $$;
create function bitd.validate_character_patch(p_patch jsonb) returns void
language plpgsql set search_path = '' as $$
begin
 perform bitd.validate_character_pre_companion_patch(p_patch-array['sparkmind','resonanceEntity','autopod','intellectual','paranormalist','swinger']);
 perform bitd.validate_character_companion_patch(p_patch);
end $$;
create function bitd.check_character_companion_state() returns trigger
language plpgsql set search_path = '' as $$
declare field text; expected text; item jsonb; resource_name text; resource_ability text; extra_types integer;
begin
 perform bitd.validate_character_companion_patch(new.data);
 foreach field in array array['sparkmind','intellectual','resonanceEntity','paranormalist','autopod','swinger'] loop
  expected := case when field in ('sparkmind','intellectual') then 'Intellectual' when field in ('resonanceEntity','paranormalist') then 'Paranormalist' else 'Swinger' end;
  if new.data ? field and new.data->>'playbook'<>expected then raise exception 'Companion record requires its saved playbook'; end if;
 end loop;
 if new.data->>'playbook'='Intellectual' then
  if jsonb_array_length(new.data->'sparkmind'->'advancedChoices')>0 and not (new.data->'abilities') ? 'Advanced Sparkmind' then raise exception 'Sparkmind improvements require Advanced Sparkmind'; end if;
  select count(*) into extra_types from jsonb_array_elements_text(new.data->'sparkmind'->'advancedChoices') c where c='additional-type';
  if jsonb_array_length(new.data->'sparkmind'->'types')>1+extra_types then raise exception 'Additional expertise requires an Advanced Sparkmind type choice'; end if;
  resource_name := 'research'; resource_ability := 'Researcher';
 elsif new.data->>'playbook'='Paranormalist' then
  if (new.data->'paranormalist'->>'precognitionUsed')::integer>0 and not (new.data->'abilities') ? 'Precognition' then raise exception 'Free assists require Precognition'; end if;
  if (new.data->'paranormalist'->>'projectionRank')::integer>0 and not (new.data->'abilities') ? 'Echo Projection' then raise exception 'Projection selections require Echo Projection'; end if;
  if (new.data->'paranormalist'->>'projectionActive')::boolean and (new.data->'paranormalist'->>'projectionRank')::integer<1 then raise exception 'Active projection requires a selected rank'; end if;
  resource_name := 'sixth sense'; resource_ability := 'Extrasensory Perception';
 elsif new.data->>'playbook'='Swinger' then
  if (new.data->'swinger'->>'hustleActivityGranted')::boolean and not (new.data->'abilities') ? 'Always Hustling' then raise exception 'Extra activity requires Always Hustling'; end if;
  if (new.data->'swinger'->>'partyAssistAvailable')::boolean and not (new.data->'abilities') ? 'Party Animal' then raise exception 'Party assist requires Party Animal'; end if;
  if ((new.data->'swinger'->>'twinSummoned')::boolean or jsonb_array_length(new.data->'swinger'->'twinFeatures')>0) and not (new.data->'abilities') ? 'Echo Twin' then raise exception 'Twin choices require Echo Twin'; end if;
  resource_name := 'mojo'; resource_ability := 'Smooth';
 end if;
 if resource_name is not null then
  for item in select * from jsonb_array_elements(new.data->'resources') loop
   if lower(trim(item->>'name'))=resource_name then
    if (item->>'capacity')::integer<>2 then raise exception 'Published companion playbook resource has two uses'; end if;
    if (item->>'used')::integer>0 and not (new.data->'abilities') ? resource_ability then raise exception 'Resource use requires %',resource_ability; end if;
   end if;
  end loop;
 end if;
 return new;
end $$;
create trigger character_companion_check before insert or update on bitd.characters for each row execute function bitd.check_character_companion_state();
-- Every top-level object has already passed the closed shape validators above and
-- their delegates. Merge its subfields one level; arrays/scalars remain atomic.
-- This exercised companion extension removes the stale per-playbook merge list.
create or replace function bitd.patch_character(p_character uuid,p_patch jsonb) returns bitd.characters
language plpgsql security definer set search_path = '' as $$
declare result bitd.characters; merged jsonb; entry record;
begin
 select * into result from bitd.characters where id=p_character for update;
 if not found or bitd.campaign_role(result.campaign_id) is null or (bitd.campaign_role(result.campaign_id)<>'gm' and result.owner_id is distinct from auth.uid()) then raise exception 'Character edit not permitted' using errcode='42501'; end if;
 perform bitd.validate_character_patch(p_patch);
 perform bitd.validate_character_playbook_patch(result.data->>'playbook',p_patch);
 merged := result.data || p_patch;
 for entry in select * from jsonb_each(p_patch) where jsonb_typeof(value)='object' loop
  merged := jsonb_set(merged,array[entry.key],coalesce(result.data->entry.key,'{}'::jsonb) || entry.value);
 end loop;
 update bitd.characters set data=merged,updated_at=clock_timestamp() where id=p_character returning * into result;
 return result;
end $$;
